/* prog22_snake_camel_convert.c
 *
 * The original binary implements a tiny utility that converts strings
 * between snake_case and camelCase.  It expects exactly two command‑line
 * arguments:
 *
 *   1. The conversion mode – either "to_camel" or "to_snake".
 *   2. The input string to be converted.
 *
 * If the argument count is wrong it prints "USAGE".
 * If the mode is not recognised it prints "INVALID_MODE".
 *
 * The conversion works on a fixed output buffer of 1024 bytes (the
 * original binary checks that the output never exceeds 0x400 bytes).
 *
 *   to_camel :  snake_case  →  camelCase
 *               – underscores are removed,
 *               – the first character of each word after an underscore
 *                 is capitalised,
 *               – all other characters are left as‑is (the original
 *                 program only dealt with lower‑case letters, but we
 *                 keep any other characters unchanged).
 *
 *   to_snake :  camelCase   →  snake_case
 *               – an underscore is inserted before each upper‑case
 *                 letter (except before the very first character),
 *               – the upper‑case letter is converted to lower‑case.
 *
 * The result is printed with puts().
 */

#include <stdio.h>
#include <string.h>
#include <ctype.h>

#define OUT_BUF_SIZE 1024

int main(int argc, char **argv)
{
    /* Argument check – the original binary expects at least 3 arguments
       (program name, mode, input). */
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }

    const char *mode = argv[1];
    const char *in   = argv[2];
    char out[OUT_BUF_SIZE];
    size_t out_len = 0;

    if (strcmp(mode, "to_camel") == 0) {
        /* Convert snake_case → camelCase */
        int capitalize_next = 0;          /* flag set after an underscore */
        for (size_t i = 0; in[i] != '\0' && out_len + 1 < OUT_BUF_SIZE; ++i) {
            char c = in[i];
            if (c == '_') {
                capitalize_next = 1;      /* next letter becomes upper case */
                continue;                 /* underscore itself is omitted */
            }
            if (capitalize_next && islower((unsigned char)c)) {
                c = (char)toupper((unsigned char)c);
            }
            capitalize_next = 0;
            out[out_len++] = c;
        }
        out[out_len] = '\0';
        puts(out);
    }
    else if (strcmp(mode, "to_snake") == 0) {
        /* Convert camelCase → snake_case */
        for (size_t i = 0; in[i] != '\0' && out_len + 1 < OUT_BUF_SIZE; ++i) {
            char c = in[i];
            if (isupper((unsigned char)c)) {
                if (out_len > 0) {               /* never prepend '_' */
                    out[out_len++] = '_';
                }
                c = (char)tolower((unsigned char)c);
            }
            out[out_len++] = c;
        }
        out[out_len] = '\0';
        puts(out);
    }
    else {
        puts("INVALID_MODE");
    }

    return 0;
}
